// Fungsi penanganan jika sheet/node kosong
const processEmptySheet = (nodeName) => {
  try {
    const rawData = $(nodeName).all();
    if (rawData.length === 1 && Object.keys(rawData[0].json).length === 0) {
      return [];
    }
    return rawData.map(item => item.json);
  } catch (e) {
    return [];
  }
};

const storyInfo = processEmptySheet('Story_Info');
const characters = processEmptySheet('Characters');
const locations = processEmptySheet('Locations');
const chapters = processEmptySheet('Chapters');
const outlineChapters = processEmptySheet('Outline_Chapter');

// Helper untuk mengekstrak angka dari Chapter Number (Mencegah bug spasi/string)
const parseChapterNum = (val) => {
  if (val === null || val === undefined) return 0;
  const cleaned = String(val).replace(/\D/g, '');
  return cleaned ? parseInt(cleaned, 10) : 0;
};

// Helper pintar untuk menemukan URL Google Doc dari properti objek apa pun
const extractDocUrl = (item) => {
  if (!item) return "";

  // 1. Cek properti umum
  if (item['Google Doc URL']) return item['Google Doc URL'];
  if (item['Doc URL']) return item['Doc URL'];
  if (item['URL']) return item['URL'];
  if (item['Link']) return item['Link'];
  if (item['Google Doc']) return item['Google Doc'];
  if (item['url']) return item['url'];

  // 2. Scan otomatis seluruh key yang mengandung kata "doc", "url", atau "link"
  for (const key of Object.keys(item)) {
    const lowerKey = key.toLowerCase();
    if ((lowerKey.includes('url') || lowerKey.includes('doc') || lowerKey.includes('link')) && typeof item[key] === 'string' && item[key].trim() !== '') {
      return item[key];
    }
  }
  return "";
};

// Helper untuk mengekstrak teks cerita
const extractChapterText = (ch) => {
  return ch.text || ch.Text || ch.content || ch.Content || ch.prose || ch.Prose || ch.Isi || ch.isi_bab || ch.naskah || "";
};

// 1. Urutkan bab yang ada di sheet Chapters berdasarkan angka Chapter Number dari TERBESAR ke TERNAMAK
const validChapters = chapters
  .map(ch => ({
    ...ch,
    parsed_num: parseChapterNum(ch['Chapter Number'])
  }))
  .filter(ch => ch.parsed_num > 0)
  .sort((a, b) => b.parsed_num - a.parsed_num);

// Dapatkan nomor bab paling tinggi yang tersimpan di sheet Chapters (misal: Bab 4)
const lastCompletedNum = validChapters.length > 0 ? validChapters[0].parsed_num : 0;

// Bab yang AKAN DITULIS saat ini (misal: Bab 4 + 1 = Bab 5)
const targetNumToWrite = lastCompletedNum + 1;

// 2. Ambil outline untuk Bab 5 dari Outline_Chapter
let currentChapterToWrite = outlineChapters.find(
  ch => parseChapterNum(ch['Chapter Number']) === targetNumToWrite
);

// Fallback jika outline Bab 5 tidak ketemu persis
if (!currentChapterToWrite) {
  currentChapterToWrite = outlineChapters.find(
    ch => String(ch.Status).trim().toLowerCase() === 'planned'
  );
}

// 3. Filter semua bab sebelum bab yang akan ditulis (Bab 1 s.d. Bab 4)
const previousChaptersList = validChapters
  .filter(ch => ch.parsed_num < (currentChapterToWrite ? parseChapterNum(currentChapterToWrite['Chapter Number']) : 999))
  .sort((a, b) => a.parsed_num - b.parsed_num);

let fullStoryText = "";
let latestPreviousChapter = null;
let latestPreviousDocUrl = "";

if (previousChaptersList.length > 0) {
  // Bab tepat sebelum bab saat ini (Elemen terakhir adalah Bab 4)
  latestPreviousChapter = previousChaptersList[previousChaptersList.length - 1];
  latestPreviousDocUrl = extractDocUrl(latestPreviousChapter);

  // Gabungkan seluruh teks bab sebelumnya
  fullStoryText = previousChaptersList
    .map(ch => {
      const chNum = ch.parsed_num;
      const chTitle = ch['Chapter Title'] || ch['Title'] || '';
      const chText = extractChapterText(ch);

      return `=== NASKAH NOVEL: BAB ${chNum}${chTitle ? ' - ' + chTitle : ''} ===\n${chText}`.trim();
    })
    .join('\n\n---\n\n');
}

if (!fullStoryText || fullStoryText.trim() === "") {
  fullStoryText = "Ini adalah Bab 1. Belum ada bab sebelumnya dalam naskah. Mulai cerita langsung dari awal.";
}

return [
  {
    json: {
      story_info: storyInfo,
      characters: characters,
      locations: locations,
      chapters: chapters,
      outline_chapter: outlineChapters,
      current_chapter: currentChapterToWrite,
      previous_chapters_list: previousChaptersList,
      latest_previous_chapter: latestPreviousChapter,
      latest_previous_doc_url: latestPreviousDocUrl,
      full_story_text: fullStoryText
    }
  }
];
